  const body = pm.response.json();

  pm.expect(body).to.have.property('data');
  pm.expect(body.data.total).to.eql(2);
  pm.expect(body.data.created).to.eql(1);
  pm.expect(body.data.failed).to.eql(1);
  pm.expect(body.data.results).to.be.an('array').with.lengthOf(2);
});

