  const body = pm.response.json();

  pm.expect(body.data.results[0].status).to.eql('created');
  pm.expect(body.data.results[0].data).to.have.property('id');
});

pm.test('Invalid request is reported without aborting import', () => {
  const body = pm.response.json();

  pm.expect(body.data.results[1].status).to.eql('failed');
  pm.expect(body.data.results[1].error.code).to.eql('VALIDATION_ERROR');
  pm.expect(body.data.results[1].error.details).to.be.an('array');
});

